    },
    {
      "card_ids": [
        "C08"
      ],
      "claim": "Thalidomide oral bioavailability was reported as probably high (80–100% at low doses) in fasting healthy volunteers after a 100 mg oral dose, supporting high F."
    },
    {
      "card_ids": [
        "C13"
      ],
      "claim": "Ketanserin absolute oral bioavailability was 55.5 ± 8.7% in ten healthy male subjects after a 60 mg oral dose, supporting high F."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
